import assert from "node:assert/strict";
import { readFile, stat } from "node:fs/promises";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";

const serverFile = "plugin/update-server.mjs";
const workerFile = "plugin/update-worker.mjs";
const skillFile = "plugin/skills/send-file-to-chat/SKILL.md";
const [serverSource, workerSource, skillSource, serverInfo, workerInfo] =
  await Promise.all([
    readFile(serverFile, "utf8"),
    readFile(workerFile, "utf8"),
    readFile(skillFile, "utf8"),
    stat(serverFile),
    stat(workerFile),
  ]);

assert.ok(serverInfo.size <= 2_000_000, `updater server is too large: ${serverInfo.size}`);
assert.ok(workerInfo.size <= 100_000, `update worker is too large: ${workerInfo.size}`);
for (const source of [serverSource, workerSource])
  assert.ok(source.includes("Generated by npm run build"));
for (const forbidden of ["TELEGRAM_BOT_TOKEN=", "BOT_TOKEN_PLACEHOLDER"])
  assert.ok(!serverSource.includes(forbidden) && !workerSource.includes(forbidden));
for (const expected of [
  "ask_question",
  "**⬆️ Обновить** / **Позже**",
  'optionId: "update"',
  "allowFreeform",
  "approvalToken",
  "Never print or quote `approvalToken`",
])
  assert.ok(skillSource.includes(expected), `skill is missing update contract: ${expected}`);

const transport = new StdioClientTransport({
  command: process.execPath,
  args: [serverFile],
  env: {
    PATH: process.env.PATH ?? "",
    PLUGIN_ROOT:
      "/tmp/iva-file-delivery-smoke/data/custom/plugins/file-delivery",
    PLUGIN_DATA:
      "/tmp/iva-file-delivery-smoke/data/plugin-data/file-delivery",
  },
  stderr: "pipe",
});
const client = new Client({ name: "bundle-smoke", version: "1.0.0" });
try {
  await client.connect(transport);
  const { tools } = await client.listTools();
  assert.deepEqual(
    tools.map(({ name }) => name).sort(),
    [
      "iva_file_delivery_update_apply",
      "iva_file_delivery_update_check",
      "iva_file_delivery_update_status",
    ],
  );
} finally {
  await client.close();
}

console.log(
  `updater bundles ok: server ${serverInfo.size} bytes, worker ${workerInfo.size} bytes; stdio MCP smoke passed`,
);
